/// Parse TOML text into a Value tree.
fn parse_toml(input : String) -> Value!String {
  let root : Map[String, Value] = {}
  let mut current_path : Array[String] = []
  for line_num in 1..=input.split("\n").length() {
    let raw = input.split("\n")[line_num - 1].to_owned()
    let trimmed = raw.trim()
    // Skip blank lines and comments
    if trimmed.is_empty() || trimmed.has_prefix("#") {
      continue
    }
    // Table header
    if trimmed.has_prefix("[") {
      if trimmed.has_prefix("[[") {
        raise "line \{line_num}: array of tables not supported"
      }
      guard trimmed.has_suffix("]") else {
        raise "line \{line_num}: malformed table header"
      }
      let header = trimmed[1:trimmed.length() - 1].trim()
      if header.is_empty() {
        raise "line \{line_num}: empty table header"
      }
      current_path = parse_key_path(header, line_num~)!
    } else {
      // key = value
      match trimmed.split_once("=") {
        None => raise "line \{line_num}: expected key = value, got: \{trimmed}"
        Some((key_part, value_part)) => {
          let key_str = key_part.trim()
          let value_str = value_part.trim()
          if key_str.is_empty() {
            raise "line \{line_num}: empty key"
          }
          let keys = parse_key_path(key_str, line_num~)!
          let val = parse_value(value_str, line_num~)!
          // Build full path: current_path + keys
          let full_path = current_path.concat(keys)
          insert_into_table(root, full_path, val, line_num~)!
        }
      }
    }
  }
  Table(root)
}

///|
/// Parse a dotted or bare key path like "a.b.c" or just "key".
fn parse_key_path(s : StringView, line_num~ : Int) -> Array[String]!String {
  let parts = s.split(".")
  let mut keys : Array[String] = []
  for part in parts {
    let key = part.trim()
    if key.is_empty() {
      raise "line \{line_num}: empty key segment in '\{s}'"
    }
    // Check for quoted keys (basic strings)
    if key.has_prefix("\"") && key.has_suffix("\"") && key.length() >= 2 {
      let inner = key[1:key.length() - 1]
      keys.push(unescape_string(inner, line_num~)!)
    } else if key.has_prefix("\"") || key.has_suffix("\"") {
      raise "line \{line_num}: malformed quoted key '\{key}'"
    } else {
      keys.push(key.to_owned())
    }
  }
  keys
}

///|
/// Insert a value at a dotted path into a table, detecting duplicates.
fn insert_into_table(
  table : Map[String, Value],
  path : Array[String],
  value : Value,
  line_num~ : Int
) -> Unit!String {
  if path.length() == 0 {
    raise "line \{line_num}: internal error: empty path"
  }
  if path.length() == 1 {
    let key = path[0]
    if table.contains(key) {
      raise "line \{line_num}: duplicate key '\{key}'"
    }
    table[key] = value
    return
  }
  let first = path[0]
  let rest = path[1:]
  match table.get(first) {
    None => {
      let sub : Map[String, Value] = {}
      table[first] = Table(sub)
      insert_into_table(sub, rest, value, line_num~)!
    }
    Some(Table(sub)) => {
      insert_into_table(sub, rest, value, line_num~)!
    }
    Some(_) => {
      raise "line \{line_num}: key '\{first}' is already a non-table value, cannot nest under it"
    }
  }
}

///|
/// Parse a TOML value: string, integer, boolean, or array.
fn parse_value(s : StringView, line_num~ : Int) -> Value!String {
  let s = s.trim()
  if s.is_empty() {
    raise "line \{line_num}: empty value"
  }
  // String
  if s.has_prefix("\"") {
    if !s.has_suffix("\"") || s.length() < 2 {
      raise "line \{line_num}: unclosed string"
    }
    let inner = s[1:s.length() - 1]
    let unescaped = unescape_string(inner, line_num~)!
    return String(unescaped)
  }
  // Array
  if s.has_prefix("[") {
    return parse_array(s, line_num~)
  }
  // Boolean
  if s == "true" {
    return Boolean(true)
  }
  if s == "false" {
    return Boolean(false)
  }
  // Integer (may have leading + or -)
  match parse_toml_int(s, line_num~) {
    Ok(i) => Integer(i)
    Err(msg) => raise msg
  }
}

///|
/// Parse a TOML array like [1, 2, "str"].
fn parse_array(s : StringView, line_num~ : Int) -> Value!String {
  if !s.has_suffix("]") {
    raise "line \{line_num}: unclosed array"
  }
  let inner = s[1:s.length() - 1].trim()
  if inner.is_empty() {
    return Array([])
  }
  let mut items : Array[Value] = []
  let mut remaining = inner
  while !remaining.is_empty() {
    let (item_str, rest) = split_array_item(remaining, line_num~)!
    let val = parse_value(item_str.trim(), line_num~)!
    items.push(val)
    remaining = rest.trim()
  }
  Array(items)
}

///|
/// Split the first array item from the rest, handling nested brackets and strings.
fn split_array_item(s : StringView, line_num~ : Int) -> (StringView, StringView)!String {
  let mut depth = 0
  let mut in_string = false
  let mut escaped = false
  let chars = s.to_array()
  for i in 0..<chars.length() {
    let c = chars[i]
    if escaped {
      escaped = false
      continue
    }
    if c == '\\' && in_string {
      escaped = true
      continue
    }
    if c == '"' {
      in_string = not(in_string)
      continue
    }
    if in_string {
      continue
    }
    if c == '[' {
      depth = depth + 1
    } else if c == ']' {
      if depth == 0 {
        raise "line \{line_num}: unexpected ']' in array"
      }
      depth = depth - 1
    } else if c == ',' && depth == 0 {
      let first = s[:i].trim()
      let rest = s[i + 1:]
      return (first, rest)
    }
  }
  // No comma found, return the whole thing
  (s.trim(), "")
}

///|
/// Unescape TOML string escape sequences: \\", \\\\, \\n, \\t.
fn unescape_string(s : StringView, line_num~ : Int) -> String!String {
  let mut result = StringBuilder::new()
  let mut i = 0
  while i < s.length() {
    let ch = s[i]
    if ch == '\\' && i + 1 < s.length() {
      let next = s[i + 1]
      if next == '"' {
        result.write_char('"')
        i = i + 2
      } else if next == '\\' {
        result.write_char('\\')
        i = i + 2
      } else if next == 'n' {
        result.write_char('\n')
        i = i + 2
      } else if next == 't' {
        result.write_char('\t')
        i = i + 2
      } else {
        raise "line \{line_num}: unknown escape sequence '\\{(next : Char)}'"
      }
    } else {
      result.write_char(s.get_char(i).unwrap()) // safe: i < length
      i = i + 1
    }
  }
  result.to_string()
}

///|
/// Parse a TOML integer (decimal, possibly signed).
fn parse_toml_int(s : StringView, line_num~ : Int) -> Result[Int, String] {
  if s.is_empty() {
    return Err("line \{line_num}: empty integer")
  }
  // Use the standard library's parse_int
  match @string.parse_int(s) {
    Ok(i) => Ok(i)
    Err(_) => Err("line \{line_num}: invalid integer '\{s}'")
  }
}
