    Array(arr) => {
      @json.Json::array(arr.map(fn(v) { v.to_json() }))
    }
    String(s) => @json.Json::string(s)
    Integer(i) => @json.Json::number(i.to_double(), repr=i.to_string())
    Boolean(b) => @json.Json::boolean(b)
  }
}

