///|
/// Split the first array item from the rest, handling nested brackets and strings.
fn split_array_item(s : StringView, line_num~ : Int) -> (StringView, StringView)!ParseError {
  let mut depth = 0
  let mut in_string = false
  let mut escaped = false
  for i in 0..<s.length() {
    let ch = s[i]
    if escaped {
      escaped = false
      continue
    }
    if ch == '\\' && in_string {
      escaped = true
      continue
    }
    if ch == '"' {
      in_string = not(in_string)
      continue
    }
    if in_string {
      continue
    }
    if ch == '[' {
      depth = depth + 1
    } else if ch == ']' {
      if depth == 0 {
        raise ParseError("line \{line_num}: unexpected ']' in array")
      }
      depth = depth - 1
    } else if ch == ',' && depth == 0 {
      let first = s[:i].trim()
      let rest = s[i + 1:]
      return (first, rest)
    }
  }
