  (s.trim(), "")
}

///|
/// Unescape TOML string escape sequences: \\", \\\\, \\n, \\t.
fn unescape_string(s : StringView, line_num~ : Int) -> String!ParseError {
  let result = StringBuilder::new()
  let mut i = 0
  while i < s.length() {
    let ch = s[i]
    if ch == '\\' && i + 1 < s.length() {
      let next = s[i + 1]
      if next == '"' {
        result.write_char('"')
        i = i + 2
      } else if next == '\\' {
        result.write_char('\\')
        i = i + 2
      } else if next == 'n' {
        result.write_char('\n')
        i = i + 2
      } else if next == 't' {
        result.write_char('\t')
        i = i + 2
      } else {
        let next_char : Char = s[i + 1]
        raise ParseError("line \{line_num}: unknown escape sequence '\\\{next_char}'")
      }
    } else {
      match s.get_char(i) {
        Some(c) => {
          result.write_char(c)
          i = i + 1
        }
        None => i = i + 1
      }
    }
  }
  result.to_string()
}

///|
/// Parse a TOML integer (decimal, possibly signed).
fn parse_toml_int(s : StringView, line_num~ : Int) -> Result[Int, String] {
  if s.is_empty() {
    return Err("line \{line_num}: empty integer")
  }
  // @string.parse_int raises, so we catch it
  @string.parse_int(s) catch {
    _ => Err("line \{line_num}: invalid integer '\{s}'")
  } noraise {
    i => Ok(i)
  }
}
