/// A TOML value: tables, arrays, strings, integers, or booleans.
pub(all) enum Value {
  Table(Map[String, Value])
  Array(Array[Value])
  String(String)
  Integer(Int)
  Boolean(Bool)
} derive(Eq, Debug)

///|
/// Convert a TOML `Value` into a `@json.Json` value.
pub fn Value::to_json(self : Value) -> @json.Json {
  match self {
    Table(m) => {
      let obj : Map[String, @json.Json] = {}
      for k, v in m {
        obj[k] = v.to_json()
      }
      @json.Json::object(obj)
    }
    Array(arr) => {
      @json.Json::array(arr.map(fn(v) { v.to_json() }))
    }
    String(s) => @json.Json::string(s)
    Integer(i) => @json.Json::number(i.to_double(), repr=i.to_string())
    Boolean(b) => @json.Json::boolean(b)
  }
}

