        i = i + 2
      } else {
        match s.get_char(i + 1) {
          Some(c) => raise ParseError("line \{line_num}: unknown escape sequence '\\\{c}'")
          None => raise ParseError("line \{line_num}: unexpected end of string after '\\'")
        }
      }
    } else {
      match s.get_char(i) {
        Some(c) => {
          result.write_char(c)
          i = i + 1
        }
        None => i = i + 1
      }
    }
  }
  result.to_string()
}

///|
/// Parse a TOML integer (decimal, possibly signed).
fn parse_toml_int(s : StringView, line_num~ : Int) -> Result[Int, String] {
  if s.is_empty() {
    return Err("line \{line_num}: empty integer")
  }
  // @string.parse_int raises, so we catch it
  @string.parse_int(s) catch {
    _ => Err("line \{line_num}: invalid integer '\{s}'")
  } noraise {
    i => Ok(i)
  }
}
