// Generated using `moon info`, DON'T EDIT IT
package "eval/tomljson"

import {
  "moonbitlang/core/debug",
}

// Values
pub fn parse(String) -> Value raise ParseError

// Errors
pub(all) suberror ParseError {
  ParseError(String)
} derive(Eq, @debug.Debug)
pub fn ParseError::message(Self) -> String

// Types and methods
pub(all) enum Value {
  Table(Map[String, Value])
  Array(Array[Value])
  String(String)
  Integer(Int)
  Boolean(Bool)
} derive(Eq, @debug.Debug)
pub fn Value::to_json(Self) -> Json

// Type aliases

// Traits

import {
  "moonbitlang/core/string",
}

///|
/// A TOML value: tables, arrays, strings, integers, or booleans.
pub(all) enum Value {
  Table(Map[String, Value])
  Array(Array[Value])
  String(String)
  Integer(Int)
  Boolean(Bool)
} derive(Eq, Debug)

///|
/// Convert a TOML `Value` into a `Json` value.
pub fn Value::to_json(self : Value) -> Json {
  match self {
    Table(m) => {
      let obj : Map[String, Json] = {}
      for k, v in m {
        obj[k] = v.to_json()
      }
      Json::object(obj)
    }
    Array(arr) => Json::array(arr.map(fn(v) { v.to_json() }))
    String(s) => Json::string(s)
    Integer(i) => Json::number(i.to_double(), repr=i.to_string())
    Boolean(b) => Json::boolean(b)
  }
}

///|
/// Parse TOML text into a `Value`.
///
/// # Raises
/// Raises `ParseError` on malformed or duplicate-key input.
pub fn parse(input : String) -> Value raise ParseError {
  parse_toml(input)
}

///|
/// Errors that can occur during TOML parsing.
pub(all) suberror ParseError {
  ParseError(String)
} derive(Eq, Debug)

///|
/// Convert ParseError to a user-facing message.
pub fn ParseError::message(self : ParseError) -> String {
  match self {
    ParseError(s) => s
  }
}

///|
/// Parse TOML text into a Value tree.
fn parse_toml(input : String) -> Value raise ParseError {
  let root : Map[String, Value] = {}
  let mut current_path : Array[String] = []
  let lines : Array[StringView] = input.split("\n").to_array()
  for line_num in 1..<=lines.length() {
    let trimmed = lines[line_num - 1].trim()
    // Skip blank lines and comments
    if trimmed.is_empty() || trimmed.has_prefix("#") {
      continue
    }
    // Table header
    if trimmed.has_prefix("[") {
      if trimmed.has_prefix("[[") {
        raise ParseError("line \{line_num}: array of tables not supported")
      }
      guard trimmed.has_suffix("]") else {
        raise ParseError("line \{line_num}: malformed table header")
      }
      let header = trimmed[1:trimmed.length() - 1].trim()
      if header.is_empty() {
        raise ParseError("line \{line_num}: empty table header")
      }
      current_path = parse_key_path(header, line_num~)
    } else {
      // key = value
      match trimmed.split_once("=") {
        None =>
          raise ParseError(
            "line \{line_num}: expected key = value, got: \{trimmed}",
          )
        Some((key_part, value_part)) => {
          let key_str = key_part.trim()
          let value_str = value_part.trim()
          if key_str.is_empty() {
            raise ParseError("line \{line_num}: empty key")
          }
          let keys = parse_key_path(key_str, line_num~)
          // Build full path: current_path + keys
          let full_path : Array[String] = []
          for k in current_path {
            full_path.push(k)
          }
          for k in keys {
            full_path.push(k)
          }
          let val = parse_value(value_str, line_num~)
          insert_into_table(root, full_path, val, line_num~)
        }
      }
    }
  }
  Table(root)
}

///|
/// Parse a dotted or bare key path like "a.b.c" or just "key".
fn parse_key_path(
  s : StringView,
  line_num~ : Int,
) -> Array[String] raise ParseError {
  let parts = s.split(".")
  let keys : Array[String] = []
  for part in parts {
    let key = part.trim()
    if key.is_empty() {
      raise ParseError("line \{line_num}: empty key segment in '\{s}'")
    }
    // Check for quoted keys (basic strings)
    if key.has_prefix("\"") && key.has_suffix("\"") && key.length() >= 2 {
      let inner = key[1:key.length() - 1]
      keys.push(unescape_string(inner, line_num~))
    } else if key.has_prefix("\"") || key.has_suffix("\"") {
      raise ParseError("line \{line_num}: malformed quoted key '\{key}'")
    } else {
      keys.push(key.to_owned())
    }
  }
  keys
}

///|
/// Insert a value at a dotted path into a table, detecting duplicates.
fn insert_into_table(
  table : Map[String, Value],
  path : Array[String],
  value : Value,
  line_num~ : Int,
) -> Unit raise ParseError {
  if path.length() == 0 {
    raise ParseError("line \{line_num}: internal error: empty path")
  }
  if path.length() == 1 {
    let key = path[0]
    if table.contains(key) {
      raise ParseError("line \{line_num}: duplicate key '\{key}'")
    }
    table[key] = value
    return
  }
  let first = path[0]
  // rest is an ArrayView (sliced)
  let rest = path[1:]
  match table.get(first) {
    None => {
      let sub : Map[String, Value] = {}
      table[first] = Table(sub)
      insert_into_table(sub, rest.to_owned(), value, line_num~)
    }
    Some(Table(sub)) =>
      insert_into_table(sub, rest.to_owned(), value, line_num~)
    Some(_) =>
      raise ParseError(
        "line \{line_num}: key '\{first}' is already a non-table value, cannot nest under it",
      )
  }
}

///|
/// Parse a TOML value: string, integer, boolean, or array.
fn parse_value(s : StringView, line_num~ : Int) -> Value raise ParseError {
  let s = s.trim()
  if s.is_empty() {
    raise ParseError("line \{line_num}: empty value")
  }
  // String
  if s.has_prefix("\"") {
    if !s.has_suffix("\"") || s.length() < 2 {
      raise ParseError("line \{line_num}: unclosed string")
    }
    let inner = s[1:s.length() - 1]
    let unescaped = unescape_string(inner, line_num~)
    return String(unescaped)
  }
  // Array
  if s.has_prefix("[") {
    return parse_array(s, line_num~)
  }
  // Boolean
  if s == "true" {
    return Boolean(true)
  }
  if s == "false" {
    return Boolean(false)
  }
  // Integer (may have leading + or -)
  match parse_toml_int(s, line_num~) {
    Ok(i) => Integer(i)
    Err(msg) => raise ParseError(msg)
  }
}

///|
/// Parse a TOML array like [1, 2, "str"].
fn parse_array(s : StringView, line_num~ : Int) -> Value raise ParseError {
  if !s.has_suffix("]") {
    raise ParseError("line \{line_num}: unclosed array")
  }
  let inner = s[1:s.length() - 1].trim()
  if inner.is_empty() {
    return Array([])
  }
  let items : Array[Value] = []
  let mut remaining = inner
  while !remaining.is_empty() {
    let (item_str, rest) = split_array_item(remaining, line_num~)
    let val = parse_value(item_str.trim(), line_num~)
    items.push(val)
    remaining = rest.trim()
  }
  Array(items)
}

///|
/// Split the first array item from the rest, handling nested brackets and strings.
fn split_array_item(
  s : StringView,
  line_num~ : Int,
) -> (StringView, StringView) raise ParseError {
  let mut depth = 0
  let mut in_string = false
  let mut escaped = false
  for i in 0..<s.length() {
    let ch = s[i]
    if escaped {
      escaped = false
      continue
    }
    if ch == '\\' && in_string {
      escaped = true
      continue
    }
    if ch == '"' {
      in_string = !in_string
      continue
    }
    if in_string {
      continue
    }
    if ch == '[' {
      depth = depth + 1
    } else if ch == ']' {
      if depth == 0 {
        raise ParseError("line \{line_num}: unexpected ']' in array")
      }
      depth = depth - 1
    } else if ch == ',' && depth == 0 {
      let first = s[:i].trim()
      let rest = s[i + 1:]
      return (first, rest)
    }
  }
  // No comma found, return the whole thing
  (s.trim(), "")
}

///|
/// Unescape TOML string escape sequences: \\", \\\\, \\n, \\t.
fn unescape_string(s : StringView, line_num~ : Int) -> String raise ParseError {
  let result = StringBuilder::new()
  let mut i = 0
  while i < s.length() {
    let ch = s[i]
    if ch == '\\' && i + 1 < s.length() {
      let next = s[i + 1]
      if next == '"' {
        result.write_char('"')
        i = i + 2
      } else if next == '\\' {
        result.write_char('\\')
        i = i + 2
      } else if next == 'n' {
        result.write_char('\n')
        i = i + 2
      } else if next == 't' {
        result.write_char('\t')
        i = i + 2
      } else {
        match s.get_char(i + 1) {
          Some(c) =>
            raise ParseError(
              "line \{line_num}: unknown escape sequence '\\\{c}'",
            )
          None =>
            raise ParseError(
              "line \{line_num}: unexpected end of string after '\\'",
            )
        }
      }
    } else {
      match s.get_char(i) {
        Some(c) => {
          result.write_char(c)
          i = i + 1
        }
        None => i = i + 1
      }
    }
  }
  result.to_string()
}

///|
/// Parse a TOML integer (decimal, possibly signed).
fn parse_toml_int(s : StringView, line_num~ : Int) -> Result[Int, String] {
  if s.is_empty() {
    return Err("line \{line_num}: empty integer")
  }
  // @string.parse_int raises, so we catch it
  try @string.parse_int(s) catch {
    _ => Err("line \{line_num}: invalid integer '\{s}'")
  } noraise {
    i => Ok(i)
  }
}

///|
/// CLI: tomljson — convert TOML to JSON.
///
/// Usage:
///   moon run --target native cmd/tomljson -- <file>
///   cat file.toml | moon run --target native cmd/tomljson -- --stdin
async fn main {
  let args = @env.args()
  let stdin_flag = args.any(fn(a) { a == "--stdin" })

  if args.length() <= 1 && !stdin_flag {
    @stdio.stderr.write("Error: provide a file path or --stdin\n")
    return
  }

  let input : String = if stdin_flag {
    @stdio.stdin.read_all().text()
  } else {
    try @fs.read_file_to_string(args[1]) catch {
      _ => {
        @stdio.stderr.write("Error reading file\n")
        return
      }
    } noraise {
      text => text
    }
  }

  // Parse and print JSON
  try {
    let value = @toml.parse(input)
    let json = value.to_json()
    @stdio.stdout.write(json.stringify())
    @stdio.stdout.write("\n")
  } catch {
    @toml.ParseError::ParseError(_) => @stdio.stderr.write("Parse error\n")
    _ => @stdio.stderr.write("Unexpected error\n")
  } noraise {
    _ => ()
  }
}

///|
test "parse simple key-value pairs" {
  let input =
    #|key = "value"
    #|count = 42
    #|enabled = true
    #|disabled = false
  let result = parse(input)
  match result {
    Value::Table(m) => {
      assert_eq(m.length(), 4)
      debug_inspect(m["key"], content="String(\"value\")")
      debug_inspect(m["count"], content="Integer(42)")
      debug_inspect(m["enabled"], content="Boolean(true)")
      debug_inspect(m["disabled"], content="Boolean(false)")
    }
    _ => fail("expected Table")
  }
}

///|
test "parse tables" {
  let input =
    #|[owner]
    #|name = "Alice"
    #|age = 30
  let result = parse(input)
  match result {
    Value::Table(m) => {
      assert_eq(m.length(), 1)
      match m["owner"] {
        Value::Table(sub) => {
          debug_inspect(sub["name"], content="String(\"Alice\")")
          debug_inspect(sub["age"], content="Integer(30)")
        }
        _ => fail("expected owner Table")
      }
    }
    _ => fail("expected root Table")
  }
}

///|
test "parse nested tables" {
  let input =
    #|[database]
    #|host = "localhost"
    #|
    #|[database.settings]
    #|timeout = 30
    #|pool = 5
  let result = parse(input)
  match result {
    Value::Table(m) =>
      match m["database"] {
        Value::Table(db) => {
          debug_inspect(db["host"], content="String(\"localhost\")")
          match db["settings"] {
            Value::Table(settings) => {
              debug_inspect(settings["timeout"], content="Integer(30)")
              debug_inspect(settings["pool"], content="Integer(5)")
            }
            _ => fail("expected settings Table")
          }
        }
        _ => fail("expected database Table")
      }
    _ => fail("expected root Table")
  }
}

